    ['three fractional digits', '2026-07-24T00:00:00.123Z', 123],
  ])('normalizes %s into an exact integer epoch-millisecond filter', async (_case, value, offset) => {
    const mounted = await mount()
    await mounted.call('session_search', {
      query: 'q',
